-- SQL Server: booking-ID -> dbo.Booking.Id
-- Bron: voorber 28 okt - FUTURE IDs op project en taak.xlsx
-- db-projectid -> Project_id; db-issueid -> Issue_id (bevestigd in BookingMap.cs).
-- 9287 unieke bookings; 70 regels zonder Booking-ID overgeslagen.
-- Lege FUTURE DB ISSUE_ID wordt NULL: bookings 84864, 82735, 78488.
-- Alleen afwijkende databasewaarden worden bijgewerkt.
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @Updates TABLE (
    BookingId bigint NOT NULL PRIMARY KEY,
    ProjectId bigint NULL,
    IssueId bigint NULL
);











BEGIN TRY
    BEGIN TRANSACTION;

    -- Stop als een booking uit het bestand niet bestaat.
    IF EXISTS (
        SELECT 1 FROM @Updates AS u
        LEFT JOIN dbo.Booking AS b WITH (UPDLOCK, HOLDLOCK) ON b.Id = u.BookingId
        WHERE b.Id IS NULL
    )
    BEGIN
        SELECT u.BookingId AS OntbrekendBookingId
        FROM @Updates AS u
        LEFT JOIN dbo.Booking AS b ON b.Id = u.BookingId
        WHERE b.Id IS NULL;
        THROW 50001, 'Een of meer booking-IDs ontbreken in dbo.Booking.', 1;
    END;

    UPDATE b
    SET b.Project_id = u.ProjectId,
        b.Issue_id = u.IssueId
    FROM dbo.Booking AS b
    INNER JOIN @Updates AS u ON u.BookingId = b.Id
    WHERE EXISTS (
        SELECT b.Project_id, b.Issue_id
        EXCEPT
        SELECT u.ProjectId, u.IssueId
    );

    SELECT @@ROWCOUNT AS AantalBijgewerkteBookings;
    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
